   526→            try {
   527→              sessionStorage.removeItem('zcc:valid');
   528→              sessionStorage.removeItem('zcc:zip');
   529→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   530→            } catch(e) {}
   531→            return;
   532→          }
   533→
   534→          // Store validation result for cart page
   535→          try {
   536→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   537→            sessionStorage.setItem('zcc:zip', zip);
   538→            sessionStorage.setItem('zcc:shop', SHOP);
   539→            // Fire custom event for other scripts to listen to
   540→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   541→              detail: { valid: data.allowed, zip: zip }
   542→            }));
