   712→  function joinWaitlist(zip, email, name, wBtn) {
   713→    wBtn.disabled = true;
   714→    var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
   715→    var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
   716→    if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
   717→    if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
   718→    if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';
   719→
   720→    var payload = { shop: SHOP, zip: zip, email: email };
   721→    if (name) payload.name = name;
   722→
   723→    fetch(API_BASE + "/api/waitlist", {
   724→      method: "POST",
